component_data_script:
raw_rows = props.get("kinds") or []
if isinstance(raw_rows, str):
	try:
		raw_rows = json.loads(raw_rows)
	except Exception:
		raw_rows = [line for line in raw_rows.split("\n") if line.strip()]
if not isinstance(raw_rows, list):
	raw_rows = []
rows = []
for raw in raw_rows:
	try:
		parts = [part.strip() for part in str(raw).split("|")]
		while len(parts) < 3:
			parts.append("")
		if parts[0] or parts[1]:
			rows.append(parts)
	except Exception:
		continue

email = str(props.get("email") or "").strip() or "studio@example.com"
subject = str(props.get("subject") or "").strip() or "Enquiry"
kinds = []
for parts in rows:
	phrase = parts[2] or parts[0].lower()
	kinds.append({
		"name": parts[0],
		"length": parts[1],
		"has_length": len(parts[1]) > 0,
		"phrase": phrase,
		"active": "true" if len(kinds) == 0 else "false",
		"checked": len(kinds) == 0,
	})
first = kinds[0]["phrase"] if kinds else ""
component.kinds = kinds
component.first_phrase = first
component.href = "mailto:" + email + "?subject=" + (subject + ": " + first).replace("%", "%25").replace(" ", "%20").replace(":", "%3A").replace("&", "%26").replace("?", "%3F")
component.component_data = {"count": len(kinds)}
